    DiscoverInstancesRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: DiscoverMaxResults, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of instances that you want Cloud Map to return in the response to a\n    <code>DiscoverInstances</code> request. If you don't specify a value for <code>MaxResults</code>, Cloud Map\n   returns up to 100 instances.</p>"}))
    DiscoverInstancesRequest.add_member(:query_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: Attributes, location_name: 'QueryParameters', traits: {"smithy.api#documentation" => "<p>Filters to scope the results based on custom attributes for the instance (for example, <code>{version=v1,\n    az=1a}</code>). Only instances that match all the specified key-value pairs are returned.</p>"}))
    DiscoverInstancesRequest.add_member(:optional_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: Attributes, location_name: 'OptionalParameters', traits: {"smithy.api#documentation" => "<p>Opportunistic filters to scope the results based on custom attributes. If there are instances that match\n   both the filters specified in both the <code>QueryParameters</code> parameter and this parameter, all of these\n   instances are returned. Otherwise, the filters are ignored, and only instances that match the filters that are\n   specified in the <code>QueryParameters</code> parameter are returned.</p>"}))
    DiscoverInstancesRequest.add_member(:health_status, Smithy::Schema::Shapes::ShapeRef.new(shape: HealthStatusFilter, location_name: 'HealthStatus', traits: {"smithy.api#documentation" => "<p>The health status of the instances that you want to discover. This parameter is ignored for services that\n   don't have a health check configured, and\n   all\n   instances are returned.</p>\n         <dl>\n            <dt>HEALTHY</dt>\n            <dd>\n               <p>Returns healthy instances.</p>\n            </dd>\n            <dt>UNHEALTHY</dt>\n            <dd>\n               <p>Returns unhealthy instances.</p>\n            </dd>\n            <dt>ALL</dt>\n            <dd>\n               <p>Returns all instances.</p>\n            </dd>\n            <dt>HEALTHY_OR_ELSE_ALL</dt>\n            <dd>\n               <p>Returns healthy instances, unless none are reporting a healthy state. In that case, return all\n      instances. This is also called failing open.</p>\n            </dd>\n         </dl>"}))
