    Service.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>Describes the systems that can be used to discover the service instances.</p>\n         <dl>\n            <dt>DNS_HTTP</dt>\n            <dd>\n               <p>The service instances can be discovered using either DNS queries or the <code>DiscoverInstances</code>\n      API operation.</p>\n            </dd>\n            <dt>HTTP</dt>\n            <dd>\n               <p>The service instances can only be discovered using the <code>DiscoverInstances</code> API\n      operation.</p>\n            </dd>\n            <dt>DNS</dt>\n            <dd>\n               <p>Reserved.</p>\n            </dd>\n         </dl>"}))
